import { sanitizeFilepath } from "./sanitize-filepath.js";
import { useEnv } from "@directus/env";
import { ForbiddenError } from "@directus/errors";
import { toArray } from "@directus/utils";
import path from "node:path";

//#region src/services/files/lib/assert-valid-storage-path.ts
/**
* Reject storage filepaths that write to "forbidden" locations
*
* @throws ForbiddenError
*
*/
function assertValidStoragePath(filepath, storage) {
	const env = useEnv();
	const location = storage || toArray(env["STORAGE_LOCATIONS"])[0];
	const storageDriver = env[`STORAGE_${location.toUpperCase()}_DRIVER`];
	const storagePath = sanitizeFilepath(env[`STORAGE_${location.toUpperCase()}_ROOT`] ?? "");
	const normalizedFilePath = sanitizeFilepath(filepath);
	const filePath = storageDriver === "local" ? sanitizeFilepath(path.join(storagePath, normalizedFilePath)) : normalizedFilePath;
	const extensionPath = sanitizeFilepath(env["EXTENSIONS_PATH"] ?? "");
	if (env["EXTENSIONS_LOCATION"] && env["EXTENSIONS_LOCATION"] === location) {
		if (extensionPath && filePath.startsWith(extensionPath + "/")) throw new ForbiddenError();
	}
	if (storageDriver === "local") {
		const tmpPath = sanitizeFilepath(env["TEMP_PATH"] ?? "");
		if (extensionPath && filePath.startsWith(extensionPath + "/")) throw new ForbiddenError();
		if (tmpPath && filePath.startsWith(tmpPath + "/")) throw new ForbiddenError();
	}
}

//#endregion
export { assertValidStoragePath };